#include <iostream>
using namespace std;
​
int main() {
    string input;
    getline(cin, input);
    // 最佳子串的起始位置
    int bestIndex = 0;
    // 窗口中最大GC数量
    int maxCount = 0;
    int left, right;
    // 滑动窗口双指针
    left = right = 0;
    int n;
    cin >> n;
​
    int tmpCount = 0;
    int intputSize = input.size();
    // 初始化第一个窗口
    for (; right < n && right < intputSize; right++) {
        if (input[right] == 'G' || input[right] == 'C') {
            tmpCount++;
        }
    }
    // 初始设置最佳子串为0-n
    bestIndex = 0;
    maxCount = tmpCount;
    // 滑动窗口
    while (right < intputSize) {
        // 窗口右移
        if (input[left] == 'G' || input[left] == 'C') {
            tmpCount--;
        }
        left++;
        if (input[right] == 'G' || input[right] == 'C') {
            tmpCount++;
        }
        right++;
        // 更新最优子串
        if (tmpCount > maxCount) {
            bestIndex = left;
            maxCount = tmpCount;
        }        
    }
    cout << input.substr(bestIndex, n);
    return 0;

}
