const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});
​
let lines = [];
​
rl.on("line", line => {
    lines.push(line.trim());
    if (lines.length === 2) {
        const s = lines[0];
        const n = parseInt(lines[1]);
        solve(s, n);
    }
});
​
function solve(s, n) {
    let left = 0, right = 0;
    let tmpCount = 0, maxCount = 0;
    let bestIndex = 0;
​
    // 初始化第一个窗口
    while (right < n && right < s.length) {
        if (s[right] === 'G' || s[right] === 'C') tmpCount++;
        right++;
    }
​
    maxCount = tmpCount;
​
    // 滑动窗口
    while (right < s.length) {
        if (s[left] === 'G' || s[left] === 'C') tmpCount--;
        left++;
        if (s[right] === 'G' || s[right] === 'C') tmpCount++;
        right++;
​
        if (tmpCount > maxCount) {
            maxCount = tmpCount;
            bestIndex = left;
        }
    }
​
    console.log(s.slice(bestIndex, bestIndex + n));
}
