    left, right := 0, 0
    tmpCount, maxCount := 0, 0
    bestIndex := 0
​
    // 初始化第一个窗口
    for right < n && right < len(s) {
        if s[right] == 'G' || s[right] == 'C' {
            tmpCount++
        }
        right++
    }
​
    maxCount = tmpCount
​
    // 滑动窗口遍历
    for right < len(s) {
        if s[left] == 'G' || s[left] == 'C' {
